  std::swap(MODULE_ID, o.MODULE_ID);
  std::swap(MODULE_VERSION, o.MODULE_VERSION);
  std::swap(MODULE_CONTENT_HASH, o.MODULE_CONTENT_HASH);
  std::swap(MODELS, o.MODELS);
  std::swap(CONTOUR_ALGORITHM, o.CONTOUR_ALGORITHM);
  std::swap(ENVIRONMENT_DATASET, o.ENVIRONMENT_DATASET);
  std::swap(TERRAIN_DATASET, o.TERRAIN_DATASET);
  std::swap(OBSTACLE_DATASET, o.OBSTACLE_DATASET);
  std::swap(COMPUTED_AT, o.COMPUTED_AT);
  std::swap(RETRIEVED_AT, o.RETRIEVED_AT);
  std::swap(LICENSE, o.LICENSE);
